-- =====================================================================
--  MUSE — OPTIONAL: the least-privilege account the web application uses
--  GENERATED by backend/scripts/build-workbench-sql.js from database/06_security.sql
--  and the GRANT lines of the migrations.
--
--  Only needed if you will run the MUSE web app against this database.
--  BEFORE RUNNING: replace CHANGE_ME_BEFORE_RUNNING below with your own password
--  and put the same password in DB_APP_PASSWORD in your .env (never commit .env).
--  Run after MUSE_Workbench_Setup.sql, as root.
-- =====================================================================
USE `muse`;
-- =====================================================================
--  MUSE — 06_security.sql   (least-privilege application account)
--  Run by backend/scripts/setup-db.js as the OWNER account, which replaces
--  muse, muse_app, localhost and CHANGE_ME_BEFORE_RUNNING from .env.
--
--  * The API connects as muse_app, never as the owner/root.
--  * It may read and write data, and EXECUTE procedures/functions.
--  * It cannot CREATE / ALTER / DROP anything, cannot GRANT, and cannot
--    UPDATE or DELETE audit_logs (append-only), nor change role/permission
--    reference data.
--  * Procedures, functions, triggers and views run with DEFINER rights
--    (the owner), so the app account needs no extra privileges for the
--    temporary tables and side effects they create.
--  * Read access to statement digests powers the admin "slow queries" panel.
-- =====================================================================
DROP USER IF EXISTS 'muse_app'@'localhost';
CREATE USER 'muse_app'@'localhost' IDENTIFIED BY 'CHANGE_ME_BEFORE_RUNNING';
GRANT SELECT, INSERT, UPDATE, DELETE ON muse.album_artists TO 'muse_app'@'localhost';
GRANT SELECT, INSERT, UPDATE, DELETE ON muse.albums TO 'muse_app'@'localhost';
GRANT SELECT, INSERT, UPDATE, DELETE ON muse.archetype_moods TO 'muse_app'@'localhost';
